import type { CSSProperties, ReactNode } from 'react'
import './styles.css'

export type ScrollPaneOrientation = 'vertical' | 'horizontal' | 'both'

export interface ScrollPaneProps {
  children: ReactNode
  orientation?: ScrollPaneOrientation
  overscrollBehavior?: CSSProperties['overscrollBehavior']
  className?: string
}

export function ScrollPane({
  children,
  orientation = 'vertical',
  overscrollBehavior = 'contain',
  className,
}: ScrollPaneProps) {
  const classes = ['cu-scroll-pane', `cu-scroll-pane--${orientation}`, className]
    .filter(Boolean)
    .join(' ')
  return (
    <div
      className={classes}
      data-ai-role="scroll-pane"
      data-ai-intent="scroll-region"
      data-ai-state="default"
      style={{ overscrollBehavior }}
    >
      {children}
    </div>
  )
}

.cu-scroll-pane {
  box-sizing: border-box;
  block-size: 100%;
  min-block-size: 0;
  min-inline-size: 0;
  overscroll-behavior: contain;
}

.cu-scroll-pane--vertical {
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-gutter: auto;
}

.cu-scroll-pane--horizontal {
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-gutter: auto;
}

.cu-scroll-pane--both {
  overflow: auto;
  scrollbar-gutter: auto;
}
